# OfficeFloor REST wiring

Domain REST endpoints are declared here as OfficeFloor YAML, served by the
`officefloor-rest-spring-boot-4-starter` inside the Spring Boot host. Put them under `rest/api/` so
their paths start with `/api/` — `SpaConfig` only lets `/api/*` reach the backend; a non-`/api/`
path returns the SPA's `index.html` instead of your endpoint. Directory nesting maps to path
segments, so `rest/api/owners.GET.yml` → `GET /api/owners`. Each route is its own file:

```
# officefloor/rest/api/<path>.GET.yml   (or .POST.yml, {param}.GET.yml, ...)
service:
  class: net.officefloor.hq.app.<SomeLogic>   # a class with a service(...) method
```

The logic class's `service(...)` method takes injected dependencies (Spring `@Service` beans, the
data layer) and a `net.officefloor.web.ObjectResponse<T>` to send the response.

(The `/actuator/health` readiness endpoint is Spring-side — Actuator — not an OfficeFloor route.)
# The ids of the sheet's descendants (its children, theirs, and so on down).
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithDescendants
  govern: [ readonly-transaction ]
# The people on the sheet, in the order they were added.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: asof
asof:
  class: net.officefloor.hq.app.history.ValidateViewAsOf
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
    public Person findByName(String sheetId, String name) {
        return withPatrons(sheetId, jdbc.query(
                "SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? AND (p.name_key = LOWER(TRIM(?))"
                        + " OR p.id IN (SELECT a.person_id FROM person_alias a WHERE a.sheet_id = ? AND a.alias_key = LOWER(TRIM(?))))",
                ROW, sheetId, name, sheetId, name)).stream().findFirst().orElse(null);
    }

    /** Whether another person on the sheet has this name, or anyone on the sheet has it as an alias, or anyone on
     *  another sheet of its tree (see {@link #treeOf}) but that person has it as a name or alias, ignoring case and
     *  surrounding spaces. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
        return (n != null && n > 0) || aliasTaken(sheetId, name) || usedInTree(sheetId, name, exceptId);
    }

    /** Whether anyone (but that person) on another sheet of the sheet's tree has this name or alias, ignoring case and
     *  surrounding spaces. */
    public boolean usedInTree(String sheetId, String name, Long exceptId) {
        java.util.Set<String> key = java.util.Set.of(name.trim().toLowerCase());
        return !java.util.Collections.disjoint(namesInTree(sheetId, exceptId), key);
    }

    /** Whether the person's name or any of their aliases is used, as a name or alias, on another sheet of their tree. */
    public boolean clashing(Person person) {
        return clashing(person, namesInTree(person.getSheetId(), person.getId()));
    }

    static boolean clashing(Person person, java.util.Set<String> used) {
        if (used.contains(person.getName().trim().toLowerCase())) {
            return true;
        }
        return person.getAliases().stream().anyMatch(a -> used.contains(a.trim().toLowerCase()));
    }

    /** The names and aliases (lower case, trimmed) of everyone, but that person, on the other sheets of the sheet's tree. */
    public java.util.Set<String> namesInTree(String sheetId, Long exceptId) {
        java.util.Set<String> found = new java.util.HashSet<>();
        long except = exceptId == null ? -1L : exceptId;
        for (String other : treeOf(sheetId)) {
            found.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet_id = ? AND id <> ?", String.class,
                    other, except));
            found.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet_id = ? AND person_id <> ?",
                    String.class, other, except));
        }
        return found;
    }

    /** The other sheets of the sheet's tree, among the sheets that exist: its parent, theirs and so on up, and its
     *  children, theirs and so on down (each once, the sheet itself never among them). */
    public List<String> treeOf(String sheetId) {
        java.util.Set<String> seen = new java.util.LinkedHashSet<>(List.of(sheetId));
        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) {
        }
        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
        while (!todo.isEmpty()) {
            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting_key = 'parent'"
                    + " AND setting_value = ? ORDER BY sheet_id", String.class, todo.poll())) {
                if (seen.add(child)) {
                    todo.add(child);
                }
            }
        }
        seen.remove(sheetId);
        return seen.stream().filter(s -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, s) > 0)
                .toList();
    }

    private String parentOf(String sheetId) {
        return jdbc.query("SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = 'parent'",
                (rs, n) -> rs.getString(1), sheetId).stream().filter(v -> v != null && !v.isBlank()).findFirst()
                .orElse(null);
    }

    /** Whether anyone on the sheet has this alias, ignoring case and surrounding spaces. */
    public boolean aliasTaken(String sheetId, String alias) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?))",
                Integer.class, sheetId, alias);
        return n != null && n > 0;
    }

    /** Give the person the alias (trimmed); false (nothing written) when the sheet has it as an alias already. */
    public boolean addAlias(Person person, String alias) {
        try {
            return jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) SELECT ?, ?, ? WHERE NOT EXISTS"
                    + " (SELECT 1 FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?)))",
                    person.getSheetId(), person.getId(), alias, person.getSheetId(), alias) == 1;
        } catch (DuplicateKeyException e) {
            return false;
import { useEffect, useState } from 'react';
import { QueryClientProvider, useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { liveQueryClient } from '../../query/queryClient';
import { SheetBody } from '../../slots/defs/sheetBody';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useClaims } from '../claims/useClaims';
import { useOverdue } from '../overdue/overdue.slot';
import { usePeople } from '../people/people.slot';
import { useSheetDueTotal } from '../rates/rates.slot';
import { showHundredths } from '../rates/useRates';

type Figures = { people: number; due: bigint; overdue: bigint };

/** The ids of the sheet's descendants: its children (the sheets naming it as their parent), theirs, and so on down. */
export const descendantsKey = (sheetId: string) => ['sheet', sheetId, 'descendants'] as const;

function useDescendants(sheetId: string) {
  return useQuery({
    queryKey: descendantsKey(sheetId),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/descendants`),
  });
}

// One sheet's figures as its own header shows them, reported up once all of them are read.
function SheetFigures({ sheetId, report }: { sheetId: string; report: (id: string, f: Figures | null) => void }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const due = useSheetDueTotal(sheetId);
  const overdue = useOverdue(sheetId).sheet.cents;
  const ready = people.data !== undefined && claims.data !== undefined;
  const count = (people.data ?? []).length;
  useEffect(() => {
    report(sheetId, ready ? { people: count, due, overdue } : null);
  }, [sheetId, report, ready, count, due, overdue]);
  useEffect(() => () => report(sheetId, null), [sheetId, report]);
  return null;
}

// The consolidated figures over the sheet and all its descendants: the people on each, and each sheet's
// due-total and overdue-total as that sheet shows them, added up. A sheet with no children shows its own. They are
// always the figures as the sheets stand now: while the screen shows the sheet as of a date, they are read live.
function Consolidated({ sheetId }: { sheetId: string; user: string }) {
  const [asOf] = useSearchParam('asof', asString);
  const descendants = useDescendants(sheetId);
  const [figures, setFigures] = useState<Map<string, Figures>>(new Map());
  const [report] = useState(() => (id: string, f: Figures | null) =>
    setFigures((m) => {
      const next = new Map(m);
      if (f === null) next.delete(id);
      else next.set(id, f);
      return next;
    }),
  );
  const sheets = descendants.data === undefined ? [] : [sheetId, ...descendants.data];
  const all = sheets.length > 0 && sheets.every((s) => figures.has(s));
  const shown = sheets.map((s) => figures.get(s)).filter((f): f is Figures => f !== undefined);
  const people = shown.reduce((n, f) => n + f.people, 0);
  const due = shown.reduce((n, f) => n + f.due, 0n);
  const overdue = shown.reduce((n, f) => n + f.overdue, 0n);
  return (
    <section data-testid="consolidated">
      {asOf === '' ? (
        sheets.map((s) => <SheetFigures key={s} sheetId={s} report={report} />)
      ) : (
        <QueryClientProvider client={liveQueryClient}>
          {sheets.map((s) => (
            <SheetFigures key={s} sheetId={s} report={report} />
          ))}
        </QueryClientProvider>
      )}
      <p>
        Consolidated people: <strong data-testid="consolidated-people-count">{all ? people : ''}</strong>{' '}
        Consolidated due total: <strong data-testid="consolidated-due-total">{all ? showHundredths(due) : ''}</strong>{' '}
        Consolidated overdue total:{' '}
        <strong data-testid="consolidated-overdue-total">{all ? showHundredths(overdue) : ''}</strong>
      </p>
      {descendants.isError && (
        <p data-testid="consolidated-error" role="alert">
          {descendants.error.message}
        </p>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: -9, Component: Consolidated });

