  if (sortBy === 'grade') sorted.sort((a, b) => (a.grade < b.grade ? -1 : a.grade > b.grade ? 1 : 0));
  if (sortBy === 'due-total') {
    sorted.sort((a, b) => {
      const ta = totals.get(a.id) ?? null;
      const tb = totals.get(b.id) ?? null;
      if (ta === null || tb === null) return ta === tb ? 0 : ta === null ? 1 : -1;
      return ta < tb ? -1 : ta > tb ? 1 : 0;
    });
  }
  return sorted;
}

